\set ON_ERROR_STOP on
begin;set local statement_timeout='8s';
\ir global/fixture.sql
create function pg_temp.gid(label text)returns uuid language sql as $$select(data->>'id')::uuid from group_results where group_results.label=gid.label$$;
grant execute on function pg_temp.gid(text)to authenticated,anon;
select pg_temp.policy('money_board',pg_temp.f('falcons'));
insert into group_results select'platform-policy',jsonb_build_object('id',platform_policy_id)from public.fundraising_allocation_policies limit 1;
set local role authenticated;select pg_temp.actor('coach');
select pg_temp.denied('team role alone cannot author allocation',format('select pg_temp.am(''allocation_policy.create'',%L)',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'team_id',pg_temp.f('falcons'),'channel','money_board','platform_policy_id',pg_temp.gid('platform-policy'),'organization_bps',10000,'destination_bps',0,'participant_bps',0,'starts_at',clock_timestamp())));
select pg_temp.actor('admin');
select pg_temp.am('delegation.create',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'person_id',pg_temp.f('coach'),'team_id',pg_temp.f('falcons'),'starts_at',clock_timestamp()-interval'1 minute','ends_at',clock_timestamp()+interval'10 minutes'),'delegation');
select pg_temp.actor('coach');
select pg_temp.am('allocation_policy.create',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'team_id',pg_temp.f('falcons'),'channel','money_board','platform_policy_id',pg_temp.gid('platform-policy'),'organization_bps',1000,'destination_bps',9000,'participant_bps',0,'starts_at',clock_timestamp()),'delegated',pg_temp.f('delegated-request'));
select pg_temp.check('bounded delegate sees exact report','SCOPE',public.boss_fundraising_allocation_read(jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'team_id',pg_temp.f('falcons')))->'can_manage'='true');
select pg_temp.denied('delegate cannot gain whole-campaign authority',format('select public.boss_fundraising_allocation_read(%L)',jsonb_build_object('campaign_id',pg_temp.fid('campaign'))));
select pg_temp.denied('delegate cannot gain sibling team authority',format('select public.boss_fundraising_allocation_read(%L)',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'team_id',pg_temp.f('wildcats'))));
select pg_temp.denied('delegate cannot create platform policy','select pg_temp.am(''platform_policy.create'',''{}'')');
select pg_temp.denied('delegate cannot subdelegate','select pg_temp.am(''delegation.create'',jsonb_build_object(''campaign_id'',pg_temp.fid(''campaign''),''team_id'',pg_temp.f(''falcons''),''person_id'',pg_temp.f(''staff''),''starts_at'',clock_timestamp(),''ends_at'',clock_timestamp()+interval''5 minutes''))');
select pg_temp.actor('admin');select pg_temp.am('delegation.revoke',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'delegation_id',pg_temp.gid('delegation')));
select pg_temp.actor('coach');
select pg_temp.denied('revoked delegate cannot replay a committed request',format('select pg_temp.am(''allocation_policy.create'',%L,null,%L)',jsonb_build_object('campaign_id',pg_temp.fid('campaign'),'team_id',pg_temp.f('falcons'),'channel','money_board','platform_policy_id',pg_temp.gid('platform-policy'),'organization_bps',1000,'destination_bps',9000,'participant_bps',0,'starts_at',clock_timestamp()),pg_temp.f('delegated-request')));
select pg_temp.actor('admin');
select pg_temp.fm('campaign.create',jsonb_build_object('organization_id',pg_temp.f('org'),'name','Synthetic ministry project','currency','USD','goal_minor',10000000,'starts_at',now()-interval'1 day','ends_at',now()+interval'30 days','scope','organization','channels',jsonb_build_array('money_board','direct_support')),'ministry-campaign');
select pg_temp.fm('campaign.publish',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'expected_version',1));
select pg_temp.am('unit_board.create',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'unit_id',pg_temp.f('sibling-unit'),'title','Synthetic ministry board','goal_minor',700000,'start_minor',100,'increment_minor',100,'tile_count',50,'visibility','public'),'ministry-board');
select pg_temp.fm('board.generate',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'board_id',pg_temp.gid('ministry-board'),'expected_version',1));
select pg_temp.fm('board.publish',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'board_id',pg_temp.gid('ministry-board'),'expected_version',2));
select pg_temp.am('destination.create',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'kind','ministry','unit_id',pg_temp.f('sibling-unit'),'board_id',pg_temp.gid('ministry-board'),'goal_minor',700000,'referrer_person_id',pg_temp.f('admin')),'ministry-destination');
select pg_temp.am('destination.publish',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'destination_id',pg_temp.gid('ministry-destination')));
select pg_temp.am('destination.create',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'kind','organization','goal_minor',10000000),'organization-destination');
select pg_temp.am('destination.publish',jsonb_build_object('campaign_id',pg_temp.fid('ministry-campaign'),'destination_id',pg_temp.gid('organization-destination')));
reset role;
update public.organization_modules set status='inactive'where organization_id=pg_temp.f('org')and module_id in(select id from public.modules where key in('sports','calendar','boss_bucks'));
select pg_temp.check('ministry board requires no Sports or Wallet','PORTABILITY',public.boss_money_board_public((select data->>'path'from group_results where label='ministry-destination'),1)->>'board_id'=pg_temp.gid('ministry-board')::text);
select pg_temp.check('new unit board does not replace organization board','ISOLATION',(boss_private.fundraising_public_context((select public_path from public.fundraising_campaigns where id=pg_temp.fid('ministry-campaign')))->>'board_id')is null);
select pg_temp.check('destination exposes no private referrer','PRIVACY',public.boss_fundraising_public((select data->>'path'from group_results where label='ministry-destination'))::text not like'%'||pg_temp.f('admin')||'%');
select public.boss_fundraising_support(jsonb_build_object('action','intent','request_id',pg_temp.f('ministry-direct'),'input',jsonb_build_object('path',(select data->>'path'from group_results where label='ministry-destination'),'capability',repeat('a',64),'display_name','Synthetic anonymous supporter','anonymous',true,'amount_minor',101)));
select pg_temp.check('ministry direct intent has canonical unit/referrer','ATTRIBUTION',(select fundraiser_id is null and provenance->>'unit_id'=pg_temp.f('sibling-unit')::text and provenance->>'referrer_person_id'=pg_temp.f('admin')::text and provenance->>'channel'='direct_support'from public.fundraising_intents where request_id=pg_temp.f('ministry-direct')));
select public.boss_fundraising_support(jsonb_build_object('action','intent','request_id',pg_temp.f('org-direct'),'input',jsonb_build_object('path',(select data->>'path'from group_results where label='organization-destination'),'capability',repeat('b',64),'display_name','Synthetic anonymous supporter','anonymous',true,'amount_minor',102)));
select pg_temp.check('organization-only donation invents no participant','ATTRIBUTION',(select fundraiser_id is null and not(provenance?'person_id')and not(provenance?'team_id')from public.fundraising_intents where request_id=pg_temp.f('org-direct')));
set constraints all immediate;
select count(*)passed_assertions,'Global exact-scope delegation and ministry destinations' suite from phase5a_assertions;rollback;
